package com.styleshop.order.controller;
import com.styleshop.order.service.ShoppingService;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class ShoppingController {private final ShoppingService service;public ShoppingController(ShoppingService s){service=s;}@GetMapping("/api/cart")public Object cart(Authentication a){return service.cart(a.getName());}@PostMapping("/api/cart/add/{productId}")public Object add(Authentication a,@PathVariable Long productId){return service.add(a.getName(),productId);}@PostMapping("/api/cart/increase/{id}")public Object increase(Authentication a,@PathVariable Long id){return service.change(a.getName(),id,1);}@PostMapping("/api/cart/decrease/{id}")public Object decrease(Authentication a,@PathVariable Long id){return service.change(a.getName(),id,-1);}@DeleteMapping("/api/cart/{id}")public Map<String,String> remove(Authentication a,@PathVariable Long id){service.remove(a.getName(),id);return Map.of("message","已移除");}@DeleteMapping("/api/cart/clear")public Map<String,String> clear(Authentication a){service.clear(a.getName());return Map.of("message","購物車已清空");}@PostMapping("/api/orders/checkout")public Object checkout(Authentication a){return service.checkout(a.getName());}@PostMapping("/api/orders/direct/{productId}")public Object orderNow(Authentication a,@PathVariable Long productId){return service.orderNow(a.getName(),productId);}@GetMapping("/api/orders")public Object orders(Authentication a){return service.list(a.getName());}@GetMapping("/api/orders/{id}")public Object order(Authentication a,@PathVariable Long id){return service.one(a.getName(),id);}@PutMapping("/api/orders/{id}/cancel")public Object cancel(Authentication a,@PathVariable Long id){return service.cancel(a.getName(),id);}@GetMapping("/internal/orders/all")public Object allOrders(){return service.listAll();}}
